import java.util.logging.Logger;

// The system under test: the National Bank of India online banking core.
class BankingSystem {
    private static final Logger log = Logger.getLogger(BankingSystem.class.getName());

    private boolean loginHealthy = true;
    private boolean transferHealthy = true;
    private boolean loanHealthy = true;
    private boolean statementHealthy = true;

    boolean login(String user) {
        log.fine(() -> "login attempt user=" + user);
        return loginHealthy;
    }

    boolean transfer(String from, String to, BigDecimal amount) {
        log.fine(() -> "transfer " + amount + " from " + from + " to " + to);
        return transferHealthy && amount.signum() > 0;
    }

    boolean applyLoan(String account, BigDecimal amount) {
        log.fine(() -> "loan apply account=" + account + " amount=" + amount);
        return loanHealthy;
    }

    boolean generateStatement(String account) {
        log.fine(() -> "statement account=" + account);
        return statementHealthy;
    }

    void breakTransfer() { this.transferHealthy = false; }
}
