package com.bank.qa.strategy;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

// Main runnable demo: smoke as a gate, then sanity, then full regression.
public class TestingStrategyDemo {
    private static final Logger log = Logger.getLogger(TestingStrategyDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        BankingSystem bank = new BankingSystem();

        List<TestCase> cases = List.of(
            new TestCase("smoke-login", TestScope.SMOKE,
                () -> bank.login("rajesh")),
            new TestCase("smoke-transfer", TestScope.SMOKE,
                () -> bank.transfer("SAV2001", "CUR3001", new BigDecimal("1"))),
            new TestCase("sanity-transfer-positive", TestScope.SANITY,
                () -> bank.transfer("SAV2001", "CUR3001", new BigDecimal("50000"))),
            new TestCase("sanity-transfer-zero-rejected", TestScope.SANITY,
                () -> !bank.transfer("SAV2001", "CUR3001", BigDecimal.ZERO)),
            new TestCase("reg-login", TestScope.REGRESSION, () -> bank.login("priya")),
            new TestCase("reg-transfer", TestScope.REGRESSION,
                () -> bank.transfer("SAV2001", "CUR3001", new BigDecimal("50000"))),
            new TestCase("reg-loan", TestScope.REGRESSION,
                () -> bank.applyLoan("SAV2001", new BigDecimal("200000"))),
            new TestCase("reg-statement", TestScope.REGRESSION,
                () -> bank.generateStatement("CUR3001"))
        );

        TestRunner runner = new TestRunner(cases);

        log.info("=== CI STAGE 1: SMOKE (gate on every deploy) ===");
        boolean smokeOk = runner.runScope(TestScope.SMOKE);
        if (!smokeOk) {
            log.severe("Smoke failed: rejecting build, skipping further tests.");
            return;
        }

        log.info("=== CI STAGE 2: SANITY (after targeted transfer change) ===");
        runner.runScope(TestScope.SANITY);

        log.info("=== CI STAGE 3: REGRESSION (before release) ===");
        runner.runScope(TestScope.REGRESSION);
    }
}

