package com.bank.qa.pyramid;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class TestPyramidDemo {
    private static final Logger log = Logger.getLogger(TestPyramidDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new PyramidLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        AccountService svc = new AccountService();

        List<LeveledTest> tests = List.of(
            // UNIT (functional) — many, fast, isolated
            new LeveledTest("unit-transfer-ok", TestLevel.UNIT, true,
                () -> svc.transfer(new BigDecimal("50000"))),
            new LeveledTest("unit-overdraft-rejected", TestLevel.UNIT, true,
                () -> !new AccountService().transfer(new BigDecimal("9999999"))),
            new LeveledTest("unit-zero-rejected", TestLevel.UNIT, true,
                () -> !new AccountService().transfer(BigDecimal.ZERO)),
            new LeveledTest("unit-balance-math", TestLevel.UNIT, true,
                () -> { AccountService s = new AccountService();
                        s.transfer(new BigDecimal("100000"));
                        return s.rajeshBalance().compareTo(new BigDecimal("900000")) == 0; }),
            // INTEGRATION (functional) — fewer
            new LeveledTest("int-service-repo", TestLevel.INTEGRATION, true,
                () -> new AccountService().transfer(new BigDecimal("1000"))),
            new LeveledTest("int-two-transfers", TestLevel.INTEGRATION, true,
                () -> { AccountService s = new AccountService();
                        return s.transfer(new BigDecimal("1")) && s.transfer(new BigDecimal("2")); }),
            // E2E (functional) — few, slow, broad
            new LeveledTest("e2e-login-transfer-balance", TestLevel.E2E, true,
                () -> new AccountService().transfer(new BigDecimal("50000"))),
            // ACCEPTANCE + NON-FUNCTIONAL (perf SLA)
            new LeveledTest("acc-transfer-journey", TestLevel.ACCEPTANCE, true,
                () -> new AccountService().transfer(new BigDecimal("50000"))),
            new LeveledTest("perf-transfer-under-sla", TestLevel.E2E, false,
                () -> { long t0 = System.nanoTime();
                        new AccountService().transfer(new BigDecimal("50000"));
                        long ms = (System.nanoTime() - t0) / 1_000_000;
                        log.info("non-functional: transfer took " + ms + "ms (SLA 100ms)");
                        return ms < 100; })
        );

        int passed = 0;
        for (LeveledTest t : tests) {
            boolean ok = t.run();
            if (ok) passed++;
            log.info((ok ? "PASS " : "FAIL ") + "[" + t.getLevel()
                    + (t.isFunctional() ? "/functional] " : "/non-functional] ") + t.getName());
        }
        log.info("Total: " + passed + "/" + tests.size() + " passed");

        new PyramidAnalyzer().analyze(tests);
    }
}

