package com.bank.qa.triage;

import java.util.*;
import java.util.logging.Logger;

// Orders defects by business priority and explains divergent combos.
class TriageService {
    private static final Logger log = Logger.getLogger(TriageService.class.getName());

    List<Defect> orderForFixing(List<Defect> defects) {
        List<Defect> sorted = new ArrayList<>(defects);
        sorted.sort(Comparator.comparing(Defect::getPriority)); // P1 first
        return sorted;
    }

    // Explain WHY severity and priority can diverge for this defect.
    void explain(Defect d) {
        String combo = d.getSeverity() + " / " + d.getPriority();
        if (d.getSeverity() == Severity.TRIVIAL
                && d.getPriority() == Priority.P1_IMMEDIATE) {
            log.warning("[" + d.getId() + "] " + combo
                + " -> LOW severity, HIGH priority: nothing broken, but "
                + d.getAffectedUsers() + " visitors see a brand embarrassment.");
        } else if (d.getSeverity() == Severity.CRITICAL
                && d.getPriority() == Priority.P4_LOW) {
            log.warning("[" + d.getId() + "] " + combo
                + " -> HIGH severity, LOW priority: serious crash but only "
                + d.getAffectedUsers() + " user(s), workaround="
                + d.hasWorkaround() + ", so scheduled later.");
        } else {
            log.info("[" + d.getId() + "] " + combo + " -> aligned.");
        }
    }
}
