package com.bank.qa.bug;

import java.util.*;
import java.util.logging.Logger;

// Validates legal state transitions and logs the defect journey.
class BugWorkflow {
    private static final Logger log = Logger.getLogger(BugWorkflow.class.getName());

    // Allowed next states from each state.
    private static final Map<BugState, Set<BugState>> ALLOWED = new EnumMap<>(BugState.class);
    static {
        ALLOWED.put(BugState.NEW, EnumSet.of(BugState.ASSIGNED, BugState.REJECTED, BugState.DUPLICATE));
        ALLOWED.put(BugState.ASSIGNED, EnumSet.of(BugState.OPEN, BugState.DEFERRED, BugState.REJECTED));
        ALLOWED.put(BugState.OPEN, EnumSet.of(BugState.FIXED, BugState.NOT_REPRODUCIBLE, BugState.DEFERRED));
        ALLOWED.put(BugState.NOT_REPRODUCIBLE, EnumSet.of(BugState.OPEN)); // after repro bundle supplied
        ALLOWED.put(BugState.FIXED, EnumSet.of(BugState.RETEST));
        ALLOWED.put(BugState.RETEST, EnumSet.of(BugState.VERIFIED, BugState.REOPENED));
        ALLOWED.put(BugState.VERIFIED, EnumSet.of(BugState.CLOSED));
        ALLOWED.put(BugState.REOPENED, EnumSet.of(BugState.ASSIGNED));
        ALLOWED.put(BugState.CLOSED, EnumSet.of(BugState.REOPENED));
    }

    void transition(Defect d, BugState to) {
        BugState from = d.getState();
        Set<BugState> allowed = ALLOWED.getOrDefault(from, EnumSet.noneOf(BugState.class));
        if (!allowed.contains(to)) {
            log.severe("[" + d.getId() + "] ILLEGAL " + from + " -> " + to);
            return;
        }
        // Guard: you may only leave NOT_REPRODUCIBLE with a complete bundle.
        if (from == BugState.NOT_REPRODUCIBLE
                && (d.getBundle() == null || !d.getBundle().isComplete())) {
            log.warning("[" + d.getId() + "] cannot leave NOT_REPRODUCIBLE: repro bundle incomplete");
            return;
        }
        d.setState(to);
        log.info("[" + d.getId() + "] " + from + " -> " + to);
    }
}
