    // Correct credential store (hashed in reality).
    private final Map<String, String> users = Map.of("rajesh", "Pass@123", "priya", "Secure#99");
    private final Map<String, Integer> failures = new HashMap<>();
    private final Set<String> locked = new HashSet<>();

    AuthResult login(String username, String password) {
        // Empty-field validation
        if (username == null || username.isBlank() || password == null || password.isBlank()) {
            return new AuthResult(AuthResult.Status.VALIDATION_ERROR, "Username and password are required.");
        }
        // Injection / XSS defense: reject dangerous payloads (parameterized in reality)
        if (looksMalicious(username) || looksMalicious(password)) {
            log.warning(() -> "Blocked malicious input for user=" + username);
            return new AuthResult(AuthResult.Status.BLOCKED_INPUT, GENERIC); // never leak SQL/stack
        }
        // Lockout check
        if (locked.contains(username)) {
            return new AuthResult(AuthResult.Status.LOCKED,
                "Account locked after too many attempts. Please reset your password.");
        }
        // Credential check (same generic message whether user missing or password wrong)
        String expected = users.get(username);
        if (expected == null || !expected.equals(password)) {
            int n = failures.merge(username, 1, Integer::sum);
            if (n >= MAX_ATTEMPTS) {
                locked.add(username);
                log.warning(() -> "Account locked: " + username);
                return new AuthResult(AuthResult.Status.LOCKED,
                    "Account locked after too many attempts. Please reset your password.");
            }
            return new AuthResult(AuthResult.Status.INVALID_CREDENTIALS, GENERIC);
        }
        failures.remove(username);
        return new AuthResult(AuthResult.Status.SUCCESS, "Welcome, " + username + ".");
    }

    private boolean looksMalicious(String s) {
        String v = s.toLowerCase();
        return v.contains("' or ") || v.contains("--") || v.contains("<script")
            || v.contains("drop table") || v.contains("1=1");
    }

    // Password masking is a UI property; expose metadata the UI test asserts.
    boolean isPasswordMasked() { return true; }
    int sessionTimeoutMinutes() { return 10; }
}
