    void runAll() {
        PaymentGateway gw = new PaymentGateway();
        Card good = new Card("4111111111111111", false, true);

        // SUCCESS
        PaymentResult ok = gw.charge("key-1", good, new BigDecimal("50000"));
        check("TC1 valid payment captured", ok.getStatus() == PaymentResult.Status.CAPTURED);

        // DUPLICATE: same idempotency key must NOT charge again
        PaymentResult dup = gw.charge("key-1", good, new BigDecimal("50000"));
        check("TC2 duplicate key echoes, no second charge",
            dup.getStatus() == PaymentResult.Status.DUPLICATE_ECHO
            && gw.payerBalance().compareTo(new BigDecimal("200000")) == 0);

        // DECLINES leave balance untouched
        PaymentGateway g2 = new PaymentGateway();
        check("TC3 expired card declined",
            g2.charge("k", new Card("x", true, true), new BigDecimal("10")).getStatus() == PaymentResult.Status.DECLINED_CARD);
        check("TC4 wrong CVV declined",
            new PaymentGateway().charge("k", new Card("x", false, false), new BigDecimal("10")).getStatus() == PaymentResult.Status.DECLINED_CVV);
        check("TC5 insufficient balance declined",
            new PaymentGateway().charge("k", good, new BigDecimal("9999999")).getStatus() == PaymentResult.Status.DECLINED_INSUFFICIENT);

        // LOST CONFIRMATION: client retries with SAME key -> still one charge
        PaymentGateway g3 = new PaymentGateway();
        g3.charge("key-X", good, new BigDecimal("1000"));
        g3.charge("key-X", good, new BigDecimal("1000")); // retry after lost confirmation
        check("TC6 lost-confirmation retry stays single charge",
            g3.payerBalance().compareTo(new BigDecimal("249000")) == 0);

        // PARTIAL REFUND capped at captured
        PaymentGateway g4 = new PaymentGateway();
        PaymentResult cap = g4.charge("key-R", good, new BigDecimal("20000"));
        g4.refund(cap.getReference(), new BigDecimal("5000"));  // partial
        PaymentResult over = g4.refund(cap.getReference(), new BigDecimal("20000")); // would exceed
        check("TC7 partial refund ok, over-refund rejected",
            over.getStatus() == PaymentResult.Status.DECLINED_INSUFFICIENT);
    }
}
