        log.info("=== Equivalence partitioning (amount 1..100000) ===");
        checkAmount(tv, new BigDecimal("-50"), false);   // below/invalid class
        checkAmount(tv, new BigDecimal("50000"), true);  // valid class
        checkAmount(tv, new BigDecimal("200000"), false);// above class

        // BOUNDARY VALUE ANALYSIS: edges where bugs cluster
        log.info("=== Boundary value analysis ===");
        checkAmount(tv, new BigDecimal("0"), false);
        checkAmount(tv, new BigDecimal("1"), true);
        checkAmount(tv, new BigDecimal("100000"), true);
        checkAmount(tv, new BigDecimal("100001"), false);

        // DECISION TABLE: all 8 combinations of 3 conditions
        log.info("=== Decision table (income, credit, age -> approve) ===");
        LoanDecision ld = new LoanDecision();
        for (int i = 0; i < 8; i++) {
            boolean inc = (i & 4) != 0, cre = (i & 2) != 0, age = (i & 1) != 0;
            boolean expect = inc && cre && age;
            boolean actual = ld.approve(inc, cre, age);
            log.info("income=" + inc + " credit=" + cre + " age=" + age
                + " -> approve=" + actual + (actual == expect ? " PASS" : " FAIL"));
        }

        // STATE TRANSITION: legal + illegal
