// Simulated transfer endpoint enforcing auth and business rules.
class TransferApi {
    // token -> role; "admin"/"user"/none
    ApiResponse transfer(String token, String from, BigDecimal amount) {
        Map<String, String> headers = new LinkedHashMap<>();
        headers.put("Content-Type", "application/json");
        headers.put("X-Correlation-Id", "corr-" + UUID.randomUUID());

        if (token == null) {
            return new ApiResponse(401, headers,
                Map.of("errorCode", "AUTH_REQUIRED", "message", "Authentication required."), 12);
        }
        if (!token.equals("user") && !token.equals("admin")) {
            return new ApiResponse(403, headers,
                Map.of("errorCode", "FORBIDDEN", "message", "You are not allowed to transfer."), 11);
        }
        if (amount.signum() <= 0) {
            return new ApiResponse(400, headers,
                Map.of("errorCode", "INVALID_AMOUNT", "message", "Amount must be positive."), 10);
        }
        if (amount.compareTo(new BigDecimal("1000000")) > 0) {
            return new ApiResponse(400, headers,
                Map.of("errorCode", "INSUFFICIENT_FUNDS", "message", "Insufficient balance."), 13);
        }
        Map<String, Object> ok = new LinkedHashMap<>();
        ok.put("transactionId", "TXN-9001");
        ok.put("amount", amount);                 // BigDecimal (number)
        ok.put("fromBalance", new BigDecimal("950000"));
        ok.put("status", "COMPLETED");
        return new ApiResponse(201, headers, ok, 85);
