// ─── File: src/main/java/com/bank/qa/uidb/DataNormalizer.java ───
package com.bank.qa.uidb;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

// Canonicalizes UI and DB values so comparison is fair.
class DataNormalizer {
    // UI money like "9,50,000.00" or "Rs 950000" -> BigDecimal scale 2.
    BigDecimal money(String uiOrDb) {
        if (uiOrDb == null || uiOrDb.isBlank()) return BigDecimal.ZERO; // null rule
        String digits = uiOrDb.replaceAll("[^0-9.]", "");
        return new BigDecimal(digits).setScale(2, java.math.RoundingMode.HALF_UP);
    }
    // UI "30 Oct 2026" and DB "2026-10-30" both -> LocalDate.
    LocalDate date(String value, String pattern) {
        return LocalDate.parse(value, DateTimeFormatter.ofPattern(pattern, Locale.ENGLISH));
    }
    // Case-insensitive names normalized to upper-case for comparison.
    String name(String s) { return s == null ? "" : s.trim().toUpperCase(Locale.ENGLISH); }
}
