// ─── File: src/main/java/com/bank/qa/dedupe/DuplicateCleaner.java ───
package com.bank.qa.dedupe;

import java.util.*;
import java.util.logging.Logger;

// Detects duplicates by key and deletes extras keeping MIN id, with verify.
class DuplicateCleaner {
    private static final Logger log = Logger.getLogger(DuplicateCleaner.class.getName());

    // GROUP BY account_no HAVING COUNT(*) > 1
    Map<String, Integer> findDuplicates(List<AccountRow> rows) {
        Map<String, Integer> counts = new LinkedHashMap<>();
        for (AccountRow r : rows) counts.merge(r.accountNo, 1, Integer::sum);
        Map<String, Integer> dups = new LinkedHashMap<>();
        counts.forEach((k, c) -> { if (c > 1) dups.put(k, c); });
        return dups;
    }

    // Keep the MIN id per account_no; return the cleaned list + delete count.
    List<AccountRow> deleteKeepingMinId(List<AccountRow> rows, List<AccountRow> backupOut) {
        Map<String, AccountRow> survivor = new LinkedHashMap<>(); // key -> min-id row
        for (AccountRow r : rows) {
            AccountRow keep = survivor.get(r.accountNo);
            if (keep == null || r.id < keep.id) survivor.put(r.accountNo, r);
        }
        // Anything not the survivor is a duplicate -> back it up, then drop.
        List<AccountRow> cleaned = new ArrayList<>();
        int deleted = 0;
        for (AccountRow r : rows) {
            if (survivor.get(r.accountNo) == r) cleaned.add(r);
            else { backupOut.add(r); deleted++; log.warning("DELETE duplicate " + r); }
        }
        log.info("Deleted " + deleted + " duplicate row(s); backed up before delete.");
        return cleaned;
    }

    // VERIFY: zero duplicates remain.
    boolean verify(List<AccountRow> rows) {
        boolean clean = findDuplicates(rows).isEmpty();
        log.info(clean ? "VERIFY OK: no duplicates remain" : "VERIFY FAILED: duplicates remain");
        return clean;
    }
}
