package com.bank.qa.data;

import java.math.BigDecimal;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicLong;

// Factory: sensible defaults, selective overrides, UNIQUE keys per worker.
class AccountFactory {
    private final int workerIndex;             // isolates data per worker
    private final AtomicLong seq = new AtomicLong();

    AccountFactory(int workerIndex) { this.workerIndex = workerIndex; }

    // Default valid account; id is unique by construction (worker + seq + uuid).
    Account newAccount() {
        return newAccount("Synthetic Customer", new BigDecimal("100000"));
    }

    // Override only what the test cares about.
    Account newAccount(String holder, BigDecimal balance) {
        String id = "W" + workerIndex + "-ACC" + seq.incrementAndGet()
                  + "-" + UUID.randomUUID().toString().substring(0, 6);
        return new Account(id, holder, balance);
    }
}
