name: E2E Tests
on:
  push: { branches: [main] }
  pull_request: { branches: [main] }

jobs:
  test:
    runs-on: ubuntu-latest
    strategy:
      fail-fast: false
      matrix:
        shard: [1, 2, 3, 4]          # shard across 4 parallel jobs
    env:
      # Non-secret, environment-specific config:
      BASE_URL: https://staging.nationalbank.example
    steps:
      - uses: actions/checkout@v4

      # Install dependencies deterministically (from lockfile), cached.
      - uses: actions/setup-node@v4
        with: { node-version: 20, cache: 'npm' }
      - run: npm ci

      # Install Playwright browsers + OS deps.
      - run: npx playwright install --with-deps

      # Run tests: per-env BASE_URL + sharded parallel execution.
      # Secrets are injected as MASKED env vars from the secret store.
      - name: Run Playwright
        env:
          BANK_USER: ${{ secrets.BANK_USER }}
          BANK_PASS: ${{ secrets.BANK_PASS }}   # never committed; masked in logs
        run: npx playwright test --shard=${{ matrix.shard }}/4

      # Collect artifacts (persist beyond the ephemeral runner).
      - name: Upload artifacts
        if: always()
        uses: actions/upload-artifact@v4
        with:
          name: playwright-report-shard-${{ matrix.shard }}
          path: |
            playwright-report/
            test-results/        # screenshots, videos, traces
          retention-days: 14

  notify:
    needs: test
    if: failure()                  # failure notification
    runs-on: ubuntu-latest
    steps:
      - name: Notify Slack on failure
        env:
          SLACK_WEBHOOK: ${{ secrets.SLACK_WEBHOOK }}
        run: |
          curl -X POST -H 'Content-type: application/json' \
            --data '{"text":"E2E failed on '"$GITHUB_SHA"' — see run artifacts/report."}' \
