package com.bank.qa.cidebug;

import java.util.*;
import java.util.logging.Logger;

// Compares two environments and flags differences that likely cause failures.
class EnvDiffer {
    private static final Logger log = Logger.getLogger(EnvDiffer.class.getName());

    List<String> diff(EnvSnapshot a, EnvSnapshot b) {
        List<String> diffs = new ArrayList<>();
        Set<String> keys = new TreeSet<>();
        keys.addAll(a.dims.keySet()); keys.addAll(b.dims.keySet());
        for (String k : keys) {
            String va = a.dims.getOrDefault(k, "<missing>");
            String vb = b.dims.getOrDefault(k, "<missing>");
            if (!va.equals(vb)) {
                diffs.add(k);
                log.warning("DIFF " + k + ": " + a.name + "=" + va + "  " + b.name + "=" + vb
                    + "  -> likely cause: " + hint(k));
            }
        }
        return diffs;
    }

    private String hint(String dimension) {
        switch (dimension) {
            case "timeZone": return "date/time/currency assertions mismatch";
            case "BANK_PASS": return "auth missing in CI -> lands on login page";
            case "BASE_URL": return "tests hit wrong/empty environment (data absent)";
            case "playwrightVersion": return "behavior/API/browser differences";
            case "os": return "fonts/rendering/file paths differ";
            case "networkAccess": return "firewall blocks app/3rd-party -> request fails";
            case "cpuCores": return "fewer cores -> oversubscribed workers time out";
            default: return "investigate";
        }
    }
}
