package com.bank.qa.classify;

import java.util.*;
import java.util.logging.Logger;

// Maps a failure's SYMPTOM to its likely CAUSE and the correct ACTION.
class FailureClassifier {
    private static final Logger log = Logger.getLogger(FailureClassifier.class.getName());

    Cause classify(Failure f) {
        String s = f.errorSignature.toLowerCase();
        if (s.contains("expected balance") || s.contains("wrong amount"))
            return Cause.PRODUCT_REGRESSION;                 // correct steps, wrong business result
        if (s.contains("schema") || s.contains("status 4") || s.contains("missing field"))
            return Cause.API_CONTRACT_CHANGE;
        if (s.contains("element not found") || s.contains("locator"))
            return Cause.CHANGED_LOCATORS;
        if (s.contains("login") || s.contains("401") || s.contains("connection refused") || s.contains("base url"))
            return Cause.AUTH_OR_ENV;
        if (s.contains("no such account") || s.contains("empty result") || s.contains("not seeded"))
            return Cause.MISSING_TEST_DATA;
        return Cause.PRODUCT_REGRESSION; // default to safe assumption: treat as possible real defect
    }

    Map<Cause, List<String>> classifyAll(List<Failure> failures) {
        Map<Cause, List<String>> groups = new EnumMap<>(Cause.class);
        for (Failure f : failures) groups.computeIfAbsent(classify(f), k -> new ArrayList<>()).add(f.test);
        return groups;
    }

    String action(Cause c) {
        switch (c) {
            case PRODUCT_REGRESSION: return "RAISE P1 DEFECT / consider rollback — product is broken";
            case API_CONTRACT_CHANGE: return "version API + update tests, OR fix product if unintended";
            case CHANGED_LOCATORS: return "update page objects — product OK";
            case AUTH_OR_ENV: return "fix secret/base URL/env — product OK";
            case MISSING_TEST_DATA: return "restore seeding — product OK";
            default: return "investigate";
        }
    }
}
