package com.bank.qa.coding;

import java.util.LinkedHashMap;
import java.util.Map;

class StringTasks {

    // First non-repeating character.
    // Time: O(n). Space: O(k) distinct chars. Edge: empty / all-repeat -> null.
    Character firstNonRepeating(String s) {
        if (s == null || s.isEmpty()) return null;          // edge: empty
        Map<Character, Integer> counts = new LinkedHashMap<>(); // preserves order
        for (char c : s.toCharArray()) counts.merge(c, 1, Integer::sum);
        for (Map.Entry<Character, Integer> e : counts.entrySet())
            if (e.getValue() == 1) return e.getKey();
        return null;                                        // edge: all repeat
    }

    // Reverse a string WITHOUT built-in reverse.
    // Time: O(n). Space: O(n). Edge: empty / single char -> itself.
    String reverse(String s) {
        if (s == null) return null;
        char[] a = s.toCharArray();
        int i = 0, j = a.length - 1;
        while (i < j) { char t = a[i]; a[i] = a[j]; a[j] = t; i++; j--; } // two pointers
        return new String(a);
        // Nuance: naive char-swap can corrupt multi-byte/combined Unicode.
    }
}
