package com.bank.qa.story;

// A snapshot of the suite's health, used to quantify before/after.
class SuiteMetrics {
    final String label;
    final double flakinessPct;    // % of runs that flaked
    final int regressionMinutes;  // wall-clock runtime
    final int testCount;          // stable tests in the suite
    final boolean gatesReleases;  // trusted enough to block merges?

    SuiteMetrics(String label, double flakinessPct, int regressionMinutes,
                 int testCount, boolean gatesReleases) {
        this.label = label; this.flakinessPct = flakinessPct;
        this.regressionMinutes = regressionMinutes; this.testCount = testCount;
        this.gatesReleases = gatesReleases;
    }

    // Measurable improvement vs a baseline.
    String improvementOver(SuiteMetrics before) {
        double flakeDrop = before.flakinessPct - this.flakinessPct;
        int timeDrop = before.regressionMinutes - this.regressionMinutes;
        int scaled = this.testCount - before.testCount;
        return String.format(
            "flakiness %.1f%% -> %.1f%% (-%.1f pts); runtime %dm -> %dm (-%dm); "
          + "tests %d -> %d (+%d); gates releases %b -> %b",
            before.flakinessPct, this.flakinessPct, flakeDrop,
            before.regressionMinutes, this.regressionMinutes, timeDrop,
            before.testCount, this.testCount, scaled,
            before.gatesReleases, this.gatesReleases);
    }
}
