package com.bank.qa.bdd;

import java.math.BigDecimal;
import java.util.*;

class Bank {
    private final Map<String, BigDecimal> balances = new HashMap<>();
    void setBalance(String who, BigDecimal b) { balances.put(who, b); }
    BigDecimal balance(String who) { return balances.getOrDefault(who, BigDecimal.ZERO); }
    // returns null on success, or an error message on rejection
    String transfer(String from, String to, BigDecimal amount) {
        if (balance(from).compareTo(amount) < 0) return "Insufficient balance";
        balances.put(from, balance(from).subtract(amount));
        balances.put(to, balance(to).add(amount));
        return null;
    }
}
