package com.bank.qa.metrics;

import java.util.*;
import java.util.logging.*;

public class PerfMetricsDemo {
    private static final Logger log = Logger.getLogger(PerfMetricsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new PmLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        MetricsCalculator calc = new MetricsCalculator();

        // 100 response times: 99 fast (~50ms) + 1 very slow (3000ms) = a slow TAIL.
        List<Long> samples = new ArrayList<>();
        for (int i = 0; i < 99; i++) samples.add(45L + (i % 10)); // ~45-54ms
        samples.add(3000L);                                        // the slow 1%
        Collections.sort(samples);

        int total = 100, failed = 2;   // 2 of 100 failed
        double windowSec = 1.0;         // completed in ~1s

        log.info("=== Key performance metrics (transfer API under load) ===");
        log.info(String.format("Average response time = %.0fms  <-- looks fine, HIDES the tail",
            calc.average(samples)));
        log.info(String.format("p50 (median) = %.0fms", calc.percentile(samples, 50)));
        log.info(String.format("p95          = %.0fms", calc.percentile(samples, 95)));
        log.info(String.format("p99          = %.0fms  <-- the slowest 1%% real users feel",
            calc.percentile(samples, 99)));
        log.info(String.format("Throughput   = %.0f req/s", calc.throughputPerSec(total, windowSec)));
        log.info(String.format("Error rate   = %.1f%%", calc.errorRatePct(failed, total)));

        double p99 = calc.percentile(samples, 99);
        log.info("SLA check (p95<200ms, p99<500ms, err<1%): "
            + (calc.percentile(samples,95) < 200 && p99 < 500 && calc.errorRatePct(failed,total) < 1
               ? "PASS" : "BREACH (p99 tail and/or error rate fail — avg was misleading)"));
    }
}

