        boolean ok = isSatisfiedBy(provider.balance("SAV2001"));
        log.info("can-i-deploy AccountsService v" + provider.version()
            + " -> " + (ok ? "YES (transfers safe)" : "NO (blocked before prod)"));
        return ok;
    }
