package com.bank.qa.chaos;

// Models a transfer cluster: healthy instances serve traffic; killing one
// should reroute, keeping the steady-state success rate high (if resilient).
class ServiceCluster {
    private int healthy;
    private final int total;
    private final boolean hasFailover;   // resilience mechanism under test

    ServiceCluster(int total, boolean hasFailover) {
        this.total = total; this.healthy = total; this.hasFailover = hasFailover;
    }

    void killInstance() { if (healthy > 0) healthy--; }      // the injected fault

    // Steady-state indicator: % of requests that succeed.
    double successRatePct() {
        if (healthy == 0) return 0;
        if (hasFailover) return 100.0;                       // reroutes to healthy
        return 100.0 * healthy / total;                      // no failover -> drops
    }
    int healthy() { return healthy; }
    int total() { return total; }
}
