package com.bank.qa.chaosexp;

// Models how a resilient service responds to each injected fault.
// Returns the OBSERVED behavior so the experiment can judge graceful vs total.
class ResilientService {
    enum Fault { KILL_POD, NETWORK_LATENCY, FILL_DISK, DB_FAILURE, BLOCK_DEPENDENCY }

    private final boolean hasFailover, hasTimeouts, handlesDiskFull, dbFallback, circuitBreaker;

    ResilientService(boolean hasFailover, boolean hasTimeouts, boolean handlesDiskFull,
                     boolean dbFallback, boolean circuitBreaker) {
        this.hasFailover = hasFailover; this.hasTimeouts = hasTimeouts;
        this.handlesDiskFull = handlesDiskFull; this.dbFallback = dbFallback;
        this.circuitBreaker = circuitBreaker;
    }

    // "GRACEFUL ..." = degraded but serving; "TOTAL FAILURE" = outage.
    String inject(Fault fault) {
        switch (fault) {
            case KILL_POD:
                return hasFailover ? "GRACEFUL: reroute to healthy instances; orchestrator restarts pod"
                                   : "TOTAL FAILURE: dropped requests (no failover)";
            case NETWORK_LATENCY:
                return hasTimeouts ? "GRACEFUL: timeout + bounded retry/backoff; bulkhead isolates slowness"
                                   : "TOTAL FAILURE: threads hang forever (no timeout)";
            case FILL_DISK:
                return handlesDiskFull ? "GRACEFUL: reject new writes cleanly, shed logs, alert"
                                       : "TOTAL FAILURE: crash/data corruption on full disk";
            case DB_FAILURE:
                return dbFallback ? "GRACEFUL: clear error / cache read; backoff + reconnect; no data loss"
                                  : "TOTAL FAILURE: service crashes when DB blips";
            case BLOCK_DEPENDENCY:
                return circuitBreaker ? "GRACEFUL: circuit opens, fail-fast + safe fallback; no cascade"
                                      : "TOTAL FAILURE: cascading failure drags down callers";
            default: return "UNKNOWN";
        }
    }
}
