    private static void run(ResilientService svc, ResilientService.Fault fault) {
        String behavior = svc.inject(fault);
        boolean graceful = behavior.startsWith("GRACEFUL");
        (graceful ? (java.util.function.Consumer<String>) log::info : log::severe)
            .accept(fault + " -> " + behavior + (graceful ? "  [PASS]" : "  [WEAKNESS TO FIX]"));
    }

    public static void main(String[] args) {
        // A resilient bank service with all mechanisms in place.
        ResilientService resilient = new ResilientService(true, true, true, true, true);
        log.info("=== Chaos suite vs RESILIENT service (expect graceful degradation) ===");
        for (ResilientService.Fault f : ResilientService.Fault.values()) run(resilient, f);

        // A fragile service missing circuit breaker + DB fallback.
        ResilientService fragile = new ResilientService(true, true, true, false, false);
        log.info("=== Chaos suite vs FRAGILE service (reveals weaknesses) ===");
        run(fragile, ResilientService.Fault.DB_FAILURE);
        run(fragile, ResilientService.Fault.BLOCK_DEPENDENCY);
    }
